import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';

test('exportCsv returns CSV string for empty invoices', () => {
  const result = exportCsv([]);
  assert.equal(result, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv includes header line', () => {
  const result = exportCsv([]);
  assert.ok(result.startsWith('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'));
});

test('exportCsv exports single invoice', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const result = exportCsv(invoices);
  const lines = result.trim().split('\n');
  assert.equal(lines.length, 2);
  assert.ok(lines[1].includes('INV-2026-0001'));
  assert.ok(lines[1].includes('C-001-NAME'));
});

test('exportCsv exports multiple invoices in order', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
    {
      customerId: 'C-002',
      issueDate: '2026-10-08',
      dueDate: '2026-11-07',
      number: 'INV-2026-0002',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const result = exportCsv(invoices);
  const lines = result.trim().split('\n');
  assert.equal(lines.length, 3);
  assert.ok(lines[1].includes('INV-2026-0001'));
  assert.ok(lines[2].includes('INV-2026-0002'));
});

test('exportCsv formats amounts as plain euros with 2 decimals', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const result = exportCsv(invoices);
  assert.ok(result.includes('85.00'));
});

test('exportCsv formats amounts with correct precision', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'ITEM', name: 'Item', qty: 3, unitPrice: 12345, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const result = exportCsv(invoices);
  // 12345 * 3 = 37035 cents = 370.35 euros
  assert.ok(result.includes('370.35'));
});

test('exportCsv handles subtotal with discount', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 10000, vatRate: 0, discountPercent: 10 }],
    },
  ];

  const result = exportCsv(invoices);
  // subtotal = 10000, discount = 1000, total = 9000
  assert.ok(result.includes('100.00'));
  assert.ok(result.includes('10.00'));
  assert.ok(result.includes('90.00'));
});

test('exportCsv handles VAT', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
    },
  ];

  const result = exportCsv(invoices);
  // subtotal = 8500, vat = 1785, total = 10285
  assert.ok(result.includes('85.00'));
  assert.ok(result.includes('17.85'));
  assert.ok(result.includes('102.85'));
});

test('exportCsv escapes customer name with comma', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  // Mock customer with comma in name
  const result = exportCsv(invoices);
  assert.ok(result.includes('C-001-NAME'));
});

test('exportCsv ends with newline', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const result = exportCsv(invoices);
  assert.ok(result.endsWith('\n'));
});

test('exportCsv includes invoice number', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const result = exportCsv(invoices);
  assert.ok(result.includes('INV-2026-0001'));
});

test('exportCsv includes issue date', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const result = exportCsv(invoices);
  assert.ok(result.includes('2026-10-07'));
});

test('exportCsv includes due date', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const result = exportCsv(invoices);
  assert.ok(result.includes('2026-11-06'));
});

test('exportCsv includes status', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const result = exportCsv(invoices);
  assert.ok(result.includes('issued'));
});

test('exportCsv calculates due correctly for issued invoice', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const result = exportCsv(invoices);
  // Due = total = 85.00
  const lines = result.trim().split('\n');
  const lastField = lines[1].split(',').pop();
  assert.equal(lastField, '85.00');
});

test('exportCsv calculates due correctly for partially paid invoice', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'partially_paid',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 10000, vatRate: 0, discountPercent: 0 }],
      payments: [{ amount: 4000, date: '2026-10-20' }],
    },
  ];

  const result = exportCsv(invoices);
  // Total = 100.00, Paid = 40.00, Due = 60.00
  const lines = result.trim().split('\n');
  const lastField = lines[1].split(',').pop();
  assert.equal(lastField, '60.00');
});

test('exportCsv handles paid invoices', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'paid',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
      payments: [{ amount: 8500, date: '2026-10-20' }],
    },
  ];

  const result = exportCsv(invoices);
  assert.ok(result.includes('paid'));
  const lines = result.trim().split('\n');
  const lastField = lines[1].split(',').pop();
  assert.equal(lastField, '0.00');
});

test('exportCsv handles multiple line items in invoice', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [
        { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 0, discountPercent: 0 },
        { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 10000, vatRate: 0, discountPercent: 0 },
      ],
    },
  ];

  const result = exportCsv(invoices);
  // subtotal = 42500 + 100000 = 142500 = 1425.00
  assert.ok(result.includes('1425.00'));
});

test('exportCsv handles voucher', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 10000, vatRate: 0, discountPercent: 0 }],
      voucher: { code: 'PROMO', amount: 2000 },
    },
  ];

  const result = exportCsv(invoices);
  // subtotal = 100.00, total = 80.00 (after voucher), due = 80.00
  const lines = result.trim().split('\n');
  const lastField = lines[1].split(',').pop();
  assert.equal(lastField, '80.00');
});

test('exportCsv handles draft invoices', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      status: 'draft',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const result = exportCsv(invoices);
  assert.ok(result.includes('draft'));
});

test('exportCsv preserves field order in header', () => {
  const result = exportCsv([]);
  const header = result.split('\n')[0];
  const fields = header.split(',');
  assert.deepEqual(fields, ['number', 'customer', 'issueDate', 'dueDate', 'status', 'subtotal', 'discount', 'vat', 'total', 'due']);
});

test('exportCsv handles complex invoice with all features', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'partially_paid',
      lines: [
        { sku: 'SERVICE', name: 'Service', qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 5 },
      ],
      payments: [{ amount: 50000, date: '2026-10-20' }],
    },
  ];

  const result = exportCsv(invoices);
  assert.ok(result.includes('INV-2026-0001'));
  assert.ok(result.includes('2026-10-07'));
  assert.ok(result.includes('partially_paid'));
});

test('exportCsv returns string type', () => {
  const result = exportCsv([]);
  assert.equal(typeof result, 'string');
});

test('exportCsv does not mutate invoices', () => {
  const invoices = [
    {
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      number: 'INV-2026-0001',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 0, discountPercent: 0 }],
    },
  ];

  const invoicesCopy = JSON.parse(JSON.stringify(invoices));
  exportCsv(invoices);
  assert.deepEqual(invoices, invoicesCopy);
});

